{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Push back to the 25% / AUD 6,000,000 starting position."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Firmly reject this structure."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Insist on the 24-month general period (or seek Amelia's approval for 18 months as a concession)."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "We must establish a separate, robust regime for Fundamental/Title claims with a 100% cap and a minimum six-year term"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "We must insist on explicit carve-outs for fraud, wilful concealment, and deliberate misconduct. No exceptions."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject the deemed disclosure concept."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Demand deletion of this clause."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "provide evidence that all conditions in the consent have been satisfied prior to Completion"
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Reject the post-completion release. Require the debt to be repaid in full from the Completion funds, with all security released simultaneously."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "They must be explicitly itemised in the funds flow as a deduction from the purchase price"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Push for a broader indemnity that covers any claims arising from the use of the Ironquay materials, not just the specific payment."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Do not accept the characterisation. We must preserve our right to full information. Insist on ongoing reporting and investigation obligations on the Seller"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Treat as a point for due diligence assessment."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Firmly oppose any attempt to apply general limitations (caps, time bars) to all claims."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Insist on independent evidence."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "NOT_ADDRESSED",
      "evidence": ""
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

